namespace sv_a4d6adf2cd174fb5a3fe961528c2910a.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Williams"] = ["9:30 AM", "10:30 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Brown"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync() => Task.FromResult(Doctors);

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorSlots.TryGetValue(doctor, out var slots))
            return Task.FromResult(slots);

        return Task.FromResult(new List<string>());
    }

    /// <summary>
    /// Validates patient/appointment data server-side.
    /// Returns a dictionary of field name -> error message for any validation failures.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Simulate outstanding balance check
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        // Simulate self-pay restriction
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors["PreferredDoctor"] = "Selected doctor does not accept self-pay patients";
        }

        // Simulate race condition on time slot
        if (timeSlot == "10:00 AM")
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_a4d6adf2cd174fb5a3fe961528c2910a.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* STEP 1: Patient Information *@
    <fieldset>
        <legend>Step 1: Patient Information</legend>

        <div class="mb-3">
            <label for="patientName" class="form-label">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.ContainsKey("Email"))
            {
                <div class="validation-message">@serverErrors["Email"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance" class="form-label">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
        }
    </fieldset>

    @* STEP 2: Appointment Details *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.PreferredDoctor"
                    @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.PreferredDoctor" />
                @if (serverErrors.ContainsKey("PreferredDoctor"))
                {
                    <div class="validation-message">@serverErrors["PreferredDoctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                    @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeslot" class="form-label">Time Slot</label>
                <InputSelect id="timeslot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.ContainsKey("TimeSlot"))
                {
                    <div class="validation-message">@serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability">Check Availability</button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked)">Book Appointment</button>
        </fieldset>
    }

    @if (bookingConfirmed)
    {
        <div class="alert alert-success mt-3">Appointment booked successfully!</div>
    }
</EditForm>

@code {
    private AppointmentFormModel Model { get; set; } = new();
    private bool showStep2;
    private bool availabilityChecked;
    private bool bookingConfirmed;
    private List<string> doctors = [];
    private List<string> availableSlots = [];
    private Dictionary<string, string> serverErrors = new();
    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Manually validate step 1 fields
        editContext ??= new EditContext(Model);

        var step1Valid = !string.IsNullOrWhiteSpace(Model.PatientName)
            && !string.IsNullOrWhiteSpace(Model.Email)
            && new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(Model.Email)
            && !string.IsNullOrWhiteSpace(Model.Phone)
            && !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (step1Valid)
        {
            showStep2 = true;
        }
        else
        {
            // Trigger full validation to show messages
            editContext = new EditContext(Model);
            editContext.Validate();
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        if (!string.IsNullOrEmpty(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                Model.PreferredDoctor,
                DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
        else
        {
            availableSlots = [];
        }
        Model.TimeSlot = string.Empty;
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        var errors = await AppointmentSvc.ValidatePatientAsync(
            Model.Email ?? "",
            Model.InsuranceProvider ?? "",
            Model.PreferredDoctor ?? "",
            Model.TimeSlot ?? "");

        if (errors.Count > 0)
        {
            serverErrors = errors;
        }
        else
        {
            availabilityChecked = true;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityChecked)
        {
            bookingConfirmed = true;
        }
    }

    public class AppointmentFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required")]
        public string? PatientName { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required")]
        [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format")]
        public string? Email { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required")]
        public string? Phone { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required")]
        public string? InsuranceProvider { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a doctor")]
        public string? PreferredDoctor { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required")]
        [FutureDate(ErrorMessage = "Date must be in the future")]
        public DateTime? AppointmentDate { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a time slot")]
        public string? TimeSlot { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason for visit is required")]
        [System.ComponentModel.DataAnnotations.StringLength(500, ErrorMessage = "Reason must be 500 characters or fewer")]
        public string? ReasonForVisit { get; set; }
    }

    public class FutureDateAttribute : System.ComponentModel.DataAnnotations.ValidationAttribute
    {
        protected override System.ComponentModel.DataAnnotations.ValidationResult? IsValid(
            object? value, System.ComponentModel.DataAnnotations.ValidationContext validationContext)
        {
            if (value is DateTime date && date.Date <= DateTime.Today)
            {
                return new System.ComponentModel.DataAnnotations.ValidationResult(ErrorMessage);
            }
            return System.ComponentModel.DataAnnotations.ValidationResult.Success;
        }
    }
}

